sys_script_include.script:
var LaunchpadUserLookup = Class.create();
LaunchpadUserLookup.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getUserDetails: function() {
        var userId = this.getParameter('sysparm_user_id');
        var result = {
            department: '',
            manager: ''
        };

        var userGR = new GlideRecord('sys_user');
        if (userGR.get(userId)) {
            result.department = userGR.getDisplayValue('department');
            result.manager = userGR.getDisplayValue('manager');
        }

        // Convert our object to a JSON string to pass it cleanly to the frontend
        return JSON.stringify(result);
    },

    type: 'LaunchpadUserLookup'
});
